#include <sys/resource.h>
static double cpuSeconds(){rusage u={};getrusage(RUSAGE_SELF,&u);return u.ru_utime.tv_sec+u.ru_utime.tv_usec/1e6+u.ru_stime.tv_sec+u.ru_stime.tv_usec/1e6;}
static void measure(const char* path,const char* pcm,double seconds,double rate,bool color,bool transitions,bool faults,bool loops){
 Decoder d(path,true);Audio audio(pcm);Renderer r;r.asset=@(path);State state;state.camera=state.creative=color;
 Frame current=d.next(),future=d.next();double decodeStart=0;audio.start(0,rate);double begin=now(),cpu=cpuSeconds(),origin=0;uint64_t published=UINT64_MAX,draws=0,skippedTotal=0,loop=0;int transition=0;bool injected=false;double queueStart=now();
 emit(@{@"kind":@"environment",@"width":@(d.w),@"height":@(d.h),@"duration":@(d.duration),@"timebase_num":@(d.tb.num),@"timebase_den":@(d.tb.den),@"backend_snapshot_fixture":@(backendOnly),@"audio_gain":@0,@"device":@(r.dev.registryID),@"configuration":@(avcodec_configuration())});
 while(now()-begin<seconds){@autoreleasepool{
 double wall=now()-begin;
 if(transitions&&transition<4&&wall>=(transition+1)*4){double old=rate;double at=audio.clock();double rates[]={2,1,.5,1};rate=rates[transition++];double t=now();r.generation++;audio.start(at,rate);origin=at;emit(@{@"kind":@"speed-transition",@"from":@(old),@"to":@(rate),@"source_origin":@(at),@"generation":@(r.generation),@"restart_ms":@((now()-t)*1000),@"wall":@(wall),@"scope":@"actual live queue restart; predecoded atempo input, not seamless streaming"});}
 if(faults&&!injected&&wall>2){injected=true;double before=audio.clock();audio.pause();double t=now();std::this_thread::sleep_for(std::chrono::milliseconds(120));double after=audio.clock();audio.resume();emit(@{@"kind":@"rapid-pause-resume",@"clock_delta":@(after-before),@"held_serial":@(r.retained?r.retained->serial:0),@"ms":@((now()-t)*1000)});
 // Withhold AudioQueue refill to establish actual queue depletion and protect/rebase.
 AudioQueueStop(audio.q,true);emit(@{@"kind":@"queue-depletion",@"scope":@"injected queue stop, not callback-detected physical underrun",@"protected_serial":@(r.retained?r.retained->serial:0)});r.generation++;audio.start(before,rate);emit(@{@"kind":@"output-recreated",@"generation":@(r.generation),@"source_origin":@(before),@"restart":@(audio.restart)});
 injectedRenderDelay=.12;emit(@{@"kind":@"render-delay",@"injected_ms":@120,@"protected_serial":@(r.retained?r.retained->serial:0),@"scope":@"producer completion wait deliberately delayed; GPU hardware stall not induced"});std::this_thread::sleep_for(std::chrono::milliseconds(100));emit(@{@"kind":@"decode-starvation",@"injected_ms":@100,@"scope":@"scheduler withholding; decoder/device stall simulated"});
 }
